    assert.deepEqual(await (await request(path)).json(), [saved, next]);
    await request(`/${first.id}`, 'PATCH', { archived: false });
    assert.deepEqual(await (await patch({ priority: 'Low' })).json(), { ...saved, priority: 'Low' });
